/// Returns a broadcast [Stream] of events from the `events` event channel.
///
/// Each call to this method creates a new [EventChannel], so it should
/// not be called multiple times for the same `instanceName`. To deliver
/// events to multiple listeners, call this method once and listen to the
/// returned broadcast stream multiple times instead.
Stream<EventBatch> events( {String instanceName = ''}) {
  if (instanceName.isNotEmpty) {
    instanceName = '.$instanceName';
  }
  final EventChannel eventsChannel =
      EventChannel('dev.flutter.pigeon.sherpa_litert.LiteRtEventApi.events$instanceName', pigeonMethodCodec);
  return eventsChannel.receiveBroadcastStream().map((dynamic event) {
    return event as EventBatch;
  });
}
    
